<template><view class="page"><HmSkeleton v-if="loading" :rows="8"/><HmError v-else-if="error" :text="error" @retry="loadDetail"/><view v-else-if="detail" class="panel"><view class="header"><image v-if="detail.logoUrl&&detail.logoAuditStatus==='PASS'" class="logo" :src="detail.logoUrl"/><view v-else class="logo placeholder">企</view><text class="name">{{detail.name}}</text></view><text class="description">{{detail.description||'暂无企业简介'}}</text><view class="row"><text>地址</text><text>{{detail.address||'待完善'}}</text></view><view class="row"><text>电话</text><text>{{detail.phone||'待完善'}}</text></view><view class="row"><text>微信</text><text>{{detail.wechat||'待完善'}}</text></view><view v-if="detail.phone" class="primary" @tap="contact">联系企业</view></view></view></template>
<script setup>
import {ref,onMounted} from 'vue';import {contentApi} from '@/api';import HmSkeleton from '@/components/HmSkeleton.vue';import HmError from '@/components/HmError.vue'
const detail=ref(null),loading=ref(true),error=ref(''),id=ref('');async function loadDetail(){loading.value=true;error.value='';try{const r=await contentApi.getCompanyDetail(id.value);detail.value=r.data}catch(e){error.value=e.message||'企业加载失败'}finally{loading.value=false}}
function contact(){uni.showActionSheet({itemList:['拨打电话','复制电话号码'],success:({tapIndex})=>{if(tapIndex===0)uni.makePhoneCall({phoneNumber:detail.value.phone});else uni.setClipboardData({data:detail.value.phone})}})}
onMounted(()=>{const p=getCurrentPages();id.value=p[p.length-1].options?.id||'';if(id.value)loadDetail();else{loading.value=false;error.value='缺少企业编号'}})
</script>
<style scoped>.page{min-height:100vh;background:#F5F7FA;padding:24rpx}.panel{background:#fff;border-radius:16rpx;padding:32rpx}.header{display:flex;align-items:center;gap:24rpx}.logo{width:128rpx;height:128rpx;border-radius:16rpx}.placeholder{display:flex;align-items:center;justify-content:center;background:#E8EDF3;color:#8291A3;font-size:44rpx}.name{font-size:38rpx;font-weight:700}.description{display:block;margin:32rpx 0;font-size:29rpx;color:#555;line-height:1.7}.row{display:flex;justify-content:space-between;gap:20rpx;padding:24rpx 0;border-top:1rpx solid #eee;font-size:28rpx;color:#666}.primary{margin-top:32rpx;text-align:center;background:#003366;color:#fff;padding:26rpx;border-radius:12rpx}</style>